"""HTTP route for the server-side AI explanation (``POST /api/ai/explain``)."""

from fastapi import APIRouter, HTTPException

from app.schemas.ai import AiExplainRequest, AiExplainResponse
from app.services import ai_service

router = APIRouter(prefix="/api/ai", tags=["ai"])


@router.post(
    "/explain",
    summary="Explain platform figures (Markov, calendar) in plain language with Gemini.",
    description=(
        "Receives figures already computed by the frontend and returns a structured "
        "reading generated by Google Gemini. The API key stays on the server "
        "(`GEMINI_API_KEY`). The model may only interpret the numbers it receives. "
        "Errors: 503 key not configured, 413 payload too large, 429 quota, 502 provider error."
    ),
    response_model=AiExplainResponse,
    response_model_by_alias=True,
)
async def explain(request: AiExplainRequest) -> AiExplainResponse:
    try:
        explanation, model, cached = await ai_service.explain(
            request.mode, request.payload, request.language
        )
    except ai_service.AiServiceError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.message) from exc
    return AiExplainResponse(model=model, cached=cached, structured=explanation)
